<script setup lang="ts">
import { Refresh, Setting, User } from '@element-plus/icons-vue'
import { onMounted, ref } from 'vue'

import {
  fetchAdminCases,
  fetchAdminSightings,
  fetchAdminStatistics,
  fetchAdminUsers,
  updateAdminCaseStatus,
  updateAdminSightingStatus,
  updateAdminUserStatus,
} from '@/api/admin'
import StatsCards from '@/components/admin/StatsCards.vue'
import { useAuthStore } from '@/stores/auth'
import type { AdminStatistics, LostCase, Sighting, UserProfile } from '@/types/domain'
import { formatDateTime, speciesLabel } from '@/utils/format'

const auth = useAuthStore(); const statistics = ref<AdminStatistics | null>(null); const users = ref<UserProfile[]>([]); const cases = ref<LostCase[]>([]); const sightings = ref<Sighting[]>([]); const tab = ref<'users' | 'cases' | 'sightings'>('users'); const loading = ref(true); const failed = ref(false); const busyKey = ref('')
async function load() { loading.value = true; failed.value = false; try { ;[statistics.value, users.value, cases.value, sightings.value] = await Promise.all([fetchAdminStatistics(), fetchAdminUsers(), fetchAdminCases(), fetchAdminSightings()]) } catch { failed.value = true } finally { loading.value = false } }
async function toggleUser(item: UserProfile) { busyKey.value = `user-${item.user_id}`; try { const updated = await updateAdminUserStatus(item.user_id, item.status === 'ACTIVE' ? 'DISABLED' : 'ACTIVE'); users.value = users.value.map((value) => value.user_id === updated.user_id ? updated : value); statistics.value = await fetchAdminStatistics() } finally { busyKey.value = '' } }
async function toggleCase(item: LostCase) { busyKey.value = `case-${item.case_id}`; try { const updated = await updateAdminCaseStatus(item.case_id, item.status === 'CLOSED' ? 'SEARCHING' : 'CLOSED'); cases.value = cases.value.map((value) => value.case_id === updated.case_id ? updated : value); statistics.value = await fetchAdminStatistics() } finally { busyKey.value = '' } }
async function setSighting(item: Sighting, status: 'ACTIVE' | 'HIDDEN' | 'INVALID') { busyKey.value = `sighting-${item.sighting_id}`; try { const updated = await updateAdminSightingStatus(item.sighting_id, status); sightings.value = sightings.value.map((value) => value.sighting_id === updated.sighting_id ? updated : value); statistics.value = await fetchAdminStatistics() } finally { busyKey.value = '' } }
onMounted(load)
</script>

<template>
  <main class="admin-page workflow-page"><div class="pf-container"><div class="workflow-heading admin-heading"><div><span class="workflow-heading__eyebrow">PLATFORM OPERATIONS</span><h1>管理员控制台</h1><p>用一页完成统计查看、账号状态与内容治理。</p></div><el-button :icon="Refresh" @click="load">刷新数据</el-button></div>
  <div v-if="loading" class="admin-loading pf-card"><el-skeleton animated :rows="10" /></div><div v-else-if="failed || !statistics" class="admin-loading pf-card"><h2>管理数据加载失败</h2><el-button type="primary" @click="load">重新加载</el-button></div><template v-else><StatsCards :statistics="statistics" /><nav class="admin-tabs pf-card"><button :class="{ active: tab === 'users' }" @click="tab = 'users'"><el-icon><User /></el-icon>账号管理 <b>{{ users.length }}</b></button><button :class="{ active: tab === 'cases' }" @click="tab = 'cases'"><el-icon><Setting /></el-icon>走失事件 <b>{{ cases.length }}</b></button><button :class="{ active: tab === 'sightings' }" @click="tab = 'sightings'"><el-icon><Setting /></el-icon>目击线索 <b>{{ sightings.length }}</b></button></nav>
  <section v-if="tab === 'users'" class="admin-table pf-card"><header><h2>用户账号</h2><span>停用账号后，其已有令牌也会立即失效</span></header><div class="admin-table__scroll"><table><thead><tr><th>用户</th><th>联系方式</th><th>角色</th><th>状态</th><th>注册时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in users" :key="item.user_id"><td><strong>{{ item.username }}</strong><small>#{{ item.user_id }}</small></td><td>{{ item.phone || item.email || '未填写' }}</td><td>{{ item.role }}</td><td><em :class="`status-${item.status.toLowerCase()}`">{{ item.status === 'ACTIVE' ? '正常' : '停用' }}</em></td><td>{{ item.created_at ? formatDateTime(item.created_at) : '—' }}</td><td><el-button size="small" :type="item.status === 'ACTIVE' ? 'danger' : 'success'" plain :disabled="item.user_id === auth.user?.user_id" :loading="busyKey === `user-${item.user_id}`" @click="toggleUser(item)">{{ item.status === 'ACTIVE' ? '停用' : '恢复' }}</el-button></td></tr></tbody></table></div></section>
  <section v-else-if="tab === 'cases'" class="admin-table pf-card"><header><h2>走失事件</h2><span>已寻回事件不可回退，避免破坏寻回事务一致性</span></header><div class="admin-table__scroll"><table><thead><tr><th>事件</th><th>地点</th><th>宠物</th><th>状态</th><th>发布时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in cases" :key="item.case_id"><td><strong>#{{ item.case_id }} {{ item.pet.name }}</strong></td><td>{{ item.address }}</td><td>{{ speciesLabel(item.pet.species) }}</td><td><em :class="`status-${item.status.toLowerCase()}`">{{ item.status }}</em></td><td>{{ formatDateTime(item.created_at) }}</td><td><el-button size="small" plain :disabled="item.status === 'REUNITED'" :loading="busyKey === `case-${item.case_id}`" @click="toggleCase(item)">{{ item.status === 'CLOSED' ? '重新开放' : '关闭事件' }}</el-button></td></tr></tbody></table></div></section>
  <section v-else class="admin-table pf-card"><header><h2>目击线索</h2><span>隐藏用于暂时下架，无效用于明确错误信息</span></header><div class="admin-table__scroll"><table><thead><tr><th>线索</th><th>位置</th><th>类型</th><th>可信度</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in sightings" :key="item.sighting_id"><td><strong>#{{ item.sighting_id }}</strong><small>{{ formatDateTime(item.seen_time) }}</small></td><td>{{ item.address }}</td><td>{{ speciesLabel(item.species) }}</td><td>{{ item.confidence }}/5</td><td><em :class="`status-${item.status.toLowerCase()}`">{{ item.status }}</em></td><td><div class="admin-actions"><el-button size="small" plain :disabled="item.status === 'ACTIVE'" @click="setSighting(item, 'ACTIVE')">公开</el-button><el-button size="small" plain :disabled="item.status === 'HIDDEN'" @click="setSighting(item, 'HIDDEN')">隐藏</el-button><el-button size="small" type="danger" plain :disabled="item.status === 'INVALID'" @click="setSighting(item, 'INVALID')">无效</el-button></div></td></tr></tbody></table></div></section></template></div></main>
</template>

<style scoped>
.admin-heading { align-items: center; }.admin-loading { padding: 28px; text-align: center; }.admin-tabs { display: flex; gap: 5px; margin: 16px 0; padding: 6px; }.admin-tabs button { display: flex; align-items: center; gap: 6px; min-height: 39px; padding: 0 14px; border: 0; border-radius: 8px; color: var(--pf-color-text-secondary); background: transparent; font-size: 10px; font-weight: 700; cursor: pointer; }.admin-tabs button.active { color: #fff; background: var(--pf-color-primary); }.admin-tabs b { display: grid; min-width: 19px; height: 19px; padding: 0 4px; place-items: center; border-radius: 99px; background: rgb(255 255 255 / 20%); font-size: 8px; }.admin-table { overflow: hidden; }.admin-table > header { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding: 18px 20px; border-bottom: 1px solid var(--pf-color-border); }.admin-table h2 { margin: 0; font-size: 16px; }.admin-table header span { color: var(--pf-color-text-tertiary); font-size: 9px; }.admin-table__scroll { overflow-x: auto; }table { width: 100%; border-collapse: collapse; font-size: 10px; }th { padding: 10px 15px; color: var(--pf-color-text-tertiary); background: var(--pf-color-surface-warm); text-align: left; white-space: nowrap; }td { padding: 12px 15px; border-top: 1px solid #f2e8e1; color: var(--pf-color-text-secondary); }td strong, td small { display: block; }td strong { color: var(--pf-color-text); }td small { color: var(--pf-color-text-tertiary); font-size: 8px; }td em { padding: 3px 7px; border-radius: 99px; background: #eee5df; font-size: 8px; font-style: normal; white-space: nowrap; }.status-active, .status-searching, .status-reunited { color: var(--pf-color-sage-dark); background: var(--pf-color-sage-soft) !important; }.status-disabled, .status-closed, .status-invalid { color: var(--pf-color-danger); background: #fff0ee !important; }.admin-actions { display: flex; gap: 4px; white-space: nowrap; }
@media (max-width: 650px) { .admin-tabs { overflow-x: auto; }.admin-tabs button { flex: 0 0 auto; }.admin-table > header { align-items: flex-start; flex-direction: column; } }
</style>
